import React, { useMemo, useState } from 'react';

const MainSection = ({ onYes }) => {
  const [hoveredCard, setHoveredCard] = useState(null);

  const reasons = [
    {
      id: 1,
      icon: '✨',
      title: 'You Make Me Smile',
      description: 'Every moment with you lights up my world',
    },
    {
      id: 2,
      icon: '❤️',
      title: 'You\'re My Safe Place',
      description: 'In your arms, I find my home',
      delay: '5s',
    },
    {
      id: 3,
      icon: '🏰',
      title: 'You\'re My Forever',
      description: 'With you, I see eternity',
      delay: '10s',
    },
    {
      id: 4,
      icon: '🔐',
      title: 'You\'re My Anchor',
      description: 'Steadfast and true',
      delay: '15s',
    },
    {
      id: 5,
      icon: '💫',
      title: 'You Complete Me',
      description: 'The missing piece of my heart',
      delay: '20s',
    },
    {
      id: 6,
      icon: '🐝',
      title: 'You\'re Amazing',
      description: 'High integrity, high quality human',
      delay: '25s',
    },
    {
      id: 7,
      icon: '🌟',
      title: 'You\'re My Star',
      description: 'You light up my darkest nights',
      delay: '30s',
    },
    {
      id: 8,
      icon: '🎵',
      title: 'You\'re My Song',
      description: 'My heart sings with you',
      delay: '35s',
    },
    {
      id: 9,
      icon: '🌹',
      title: 'You\'re Beautiful',
      description: 'Inside and out',
      delay: '40s',
    },
    {
      id: 10,
      icon: '✈️',
      title: 'My Adventure',
      description: 'Let\'s explore forever together',
      delay: '45s',
    },
    {
      id: 11,
      icon: '🎁',
      title: 'My Greatest Gift',
      description: 'You\'re all I ever needed',
      delay: '50s',
    },
    {
      id: 12,
      icon: '🌈',
      title: 'You\'re My Rainbow',
      description: 'After every storm comes you',
    },
  ];

  const alignments = [
    'items-start justify-start text-left',
    'items-start justify-end text-right',
    'items-end justify-start text-left',
    'items-end justify-end text-right',
    'items-center justify-center text-center',
  ];

  const rows = 6;
  const cols = 8;
  const totalCards = rows * cols;
  const gridCards = useMemo(() => {
    return Array.from({ length: totalCards }, (_, index) => {
      const reason = reasons[index % reasons.length];
      return {
        id: index + 1,
        reason,
        alignment: alignments[index % alignments.length],
        delay: `${(index % 12) * 0.4}s`,
        showText: Math.random() > 0.35,
      };
    });
  }, [totalCards, reasons]);

  return (
    <div className="relative w-full min-h-screen overflow-hidden px-4 py-6 md:py-8">
      {/* Background grid of cards */}
      <div className="absolute inset-0">
        <div className="grid grid-cols-3 grid-rows-10 gap-2 p-3 sm:grid-cols-4 sm:grid-rows-8 sm:p-4 md:grid-cols-8 md:grid-rows-6 md:gap-3 md:p-8">
          {gridCards.map((card) => (
            <div
              key={card.id}
              className={`grid-card flex p-3 md:p-4 ${card.alignment} animate-drift`}
              style={{
                animationDelay: card.delay,
              }}
              onMouseEnter={() => setHoveredCard(card.id)}
              onMouseLeave={() => setHoveredCard(null)}
            >
              {card.showText && (
                <div className={`text-[10px] md:text-xs leading-tight uppercase tracking-wide ${hoveredCard === card.id ? 'opacity-100' : 'opacity-80'}`}>
                  <div className="text-white/90 font-semibold">{card.reason.title}</div>
                  <div className="text-white/70 mt-1 normal-case tracking-normal">
                    {card.reason.description}
                  </div>
                </div>
              )}
            </div>
          ))}
        </div>
      </div>

      {/* Main question overlay */}
      <div className="relative z-10 flex min-h-screen items-center justify-center">
        <div className="text-center max-w-3xl px-4">
          <h2 className="text-3xl md:text-5xl lg:text-6xl font-bold mb-5 text-white" style={{ fontFamily: "'Playfair Display', serif" }}>
            So… will you be my <span className="text-white" style={{ fontFamily: "'Dancing Script', cursive" }}>Valentine?</span>
          </h2>

          <div className="flex gap-3 justify-center flex-col md:flex-row">
            <button
              onClick={onYes}
              className="px-8 py-4 bg-white text-[#E1280B] font-bold text-lg rounded-full shadow-xl hover:shadow-2xl hover:scale-105 active:scale-95 transition-all duration-300"
            >
              Yes! ❤️
            </button>

            <button
              onClick={onYes}
              className="px-8 py-4 border-2 border-white text-white font-bold text-lg rounded-full shadow-lg hover:shadow-xl hover:bg-white/10 hover:scale-105 active:scale-95 transition-all duration-300"
            >
              Of course! 😌
            </button>
          </div>

          <p className="text-white/80 mt-4 italic text-sm text-center">
            Spoiler: Both answers lead to the same happy ending 💕
          </p>
        </div>
      </div>
    </div>
  );
};

export default MainSection;
